        public static readonly SAVE_BITS_MEGA_STRING: number = 3;	// 傳給server時用於紀錄超大字串長度的位元組數.
        public static readonly SAVE_BITS_STRING: number = 2; // 傳給server時用於紀錄字串長度的位元組數.
