            let fValue: number = 0;
            let bSucceed: boolean = true;
            try {
                fValue = this.m_DataView.getInt32(this.m_nReadIndex, this.USE_LITTLE_ENDIAN);
                this.m_nReadIndex += 4;
            } catch (error) {
                bSucceed = false;
            }
            return [bSucceed, fValue];
        }
        public getUint8(): [boolean, number] {
            if (this.getUnreadCount() < 1) {
                return [false, 0];
            }
            let fValue: number = 0;
            let bSucceed: boolean = true;
            try {
                fValue = this.m_DataView.getUint8(this.m_nReadIndex);
                this.m_nReadIndex += 1;
            } catch (error) {
                bSucceed = false;
            }
            return [bSucceed, fValue];
        }
        /**
         * 取出一個unit8的數值, 但不改變已讀位置.
         */
        public peekUint8(): [boolean, number] {
            if (this.getUnreadCount() < 1) {
                return [false, 0];
            }
            let fValue: number = 0;
            let bSucceed: boolean = true;
            try {
                fValue = this.m_DataView.getUint8(this.m_nReadIndex);
            } catch (error) {
                bSucceed = false;
            }
            return [bSucceed, fValue];
        }

        public getUint16(): [boolean, number] {
            if (this.getUnreadCount() < 2) {
                return [false, 0];
            }
            let fValue: number = 0;
            let bSucceed: boolean = true;
            try {
                fValue = this.m_DataView.getUint16(this.m_nReadIndex, this.USE_LITTLE_ENDIAN);
                this.m_nReadIndex += 2;
            } catch (error) {
                bSucceed = false;
            }
            return [bSucceed, fValue];
        }

        public getUint32(): [boolean, number] {
            if (this.getUnreadCount() < 4) {
                return [false, 0];
            }
            let fValue: number = 0;
            let bSucceed: boolean = true;
            try {
                fValue = this.m_DataView.getUint32(this.m_nReadIndex, this.USE_LITTLE_ENDIAN);
                this.m_nReadIndex += 4;
            } catch (error) {
                bSucceed = false;
            }
            return [bSucceed, fValue];
        }

        public getUint32ByBig(): [boolean, number] {
            if (this.getUnreadCount() < 4) {
                return [false, 0];
            }
            let fValue: number = 0;
            let bSucceed: boolean = true;
            try {
                fValue = this.m_DataView.getUint32(this.m_nReadIndex, false);
                this.m_nReadIndex += 4;
            } catch (error) {
                bSucceed = false;
            }
            return [bSucceed, fValue];
        }
        public getLong(bUnsigned: boolean = false): [boolean, dcodeIO.Long] {
            return this.getPositiveLong(8, bUnsigned);
        }

        public getPositiveLongByBig(iDigits: number, bUnsigned: boolean = true): [boolean, dcodeIO.Long] {
            if (this.getUnreadCount() < iDigits || iDigits < 0 || iDigits > 8) {
                return [false, dcodeIO.Long.ZERO];
            }
            let bSucceed: boolean = true;
            let lValue: dcodeIO.Long = dcodeIO.Long.fromNumber(0, bUnsigned);
            try {
                for (let i = iDigits - 1; i >= 0; i--) {

                    lValue = lValue.add(dcodeIO.Long.fromNumber(this.m_DataView.getUint8(this.m_nReadIndex)).shiftLeft(8 * i));
                    this.m_nReadIndex++;
                    // xsh5core.Log.info("getLong pos: " + i + " => " + this.m_DataView.getUint8(this.m_nReadIndex + i));
                }
                // this.m_nReadIndex += 1;
            } catch (error) {
                bSucceed = false;
            }

            return [bSucceed, lValue];


        }
        public getPositiveLong(iDigits: number, bUnsigned: boolean = true): [boolean, dcodeIO.Long] {
            if (this.getUnreadCount() < iDigits || iDigits < 0 || iDigits > 8) {
                return [false, dcodeIO.Long.ZERO];
            }
            let bSucceed: boolean = true;
            let lValue: dcodeIO.Long = dcodeIO.Long.fromNumber(0, bUnsigned);
            try {
                for (let i = 0; i < iDigits; ++i) {
                    lValue = lValue.add(dcodeIO.Long.fromNumber(this.m_DataView.getUint8(this.m_nReadIndex + i)).shiftLeft(8 * i));
                    // Log.info("getLong pos: " + i + " => " + this.m_DataView.getUint8(this.m_nReadIndex + i));
                }
                this.m_nReadIndex += iDigits;
            } catch (error) {
                bSucceed = false;
            }

            return [bSucceed, lValue];
        }

        public getCount(): number {
            if (!this.m_DataView) {
                return 0;
            }
            return this.m_DataView.byteLength;
        }

        public getUnreadCount(): number {
            return this.m_Buffer.byteLength - this.m_nReadIndex;
        }
        /**
         * 讀取剩於資料轉成int
         */
        public getUnreadUint8Array(): [boolean, Uint8Array] {
            let dataInt8Array: number[] = [];

            if (this.getUnreadCount() <= 0) {
                return [false, null];
            }
            let bSucceed: boolean = true;
            try {
                while (this.getUnreadCount() > 0) {
                    dataInt8Array.push(this.m_DataView.getUint8(this.m_nReadIndex));
                    this.m_nReadIndex += 1;
                }

            } catch (error) {
                bSucceed = false;
            }
            return [true, new Uint8Array(dataInt8Array)];
        }

        //add by humbert
        public getUInt24(): [boolean, number] {
            if (this.getUnreadCount() < 3) {
                return [false, 0];
            }
            let fValue: number = 0;
            let bSucceed: boolean = true;
            try {
                for (let i = 2; i >= 0; i--) {
                    fValue += this.m_DataView.getUint8(this.m_nReadIndex) * Math.pow(256, i);
                    this.m_nReadIndex++;
                }
            } catch (error) {
                bSucceed = false;
            }
            return [bSucceed, fValue];
        }

        /**
         *  utf-8陣列轉成字串(Javascript應該是utf-16).
         */
        protected fromUTF8Array(buffer: ArrayBuffer): string { // array of bytes
            var str = '', i;
            let iCount: number = buffer.byteLength;
            let dataView: DataView = new DataView(buffer);
            for (i = 0; i < iCount; i++) {
                var value = dataView.getUint8(i);
                if (value < 0x80) {
                    str += String.fromCharCode(value);
                } else if (value > 0xBF && value < 0xE0) {
                    str += String.fromCharCode((value & 0x1F) << 6 | dataView.getUint8(i + 1) & 0x3F);
                    i += 1;
                } else if (value > 0xDF && value < 0xF0) {
                    str += String.fromCharCode((value & 0x0F) << 12 | (dataView.getUint8(i + 1) & 0x3F) << 6 | dataView.getUint8(i + 2) & 0x3F);
                    i += 2;
                } else {
                    // surrogate pair
                    var charCode = ((value & 0x07) << 18 | (dataView.getUint8(i + 1) & 0x3F) << 12 | (dataView.getUint8(i + 2) & 0x3F) << 6 | dataView.getUint8(i + 3) & 0x3F) - 0x010000;

                    str += String.fromCharCode(charCode >> 10 | 0xD800, charCode & 0x03FF | 0xDC00);
                    i += 3;
                }
            }
            return str.toString();
        }

        public static fromInt8Array(data: number[]): BinaryBuffer {
            let buffer = new ArrayBuffer(data.length);
            let view = new Int8Array(buffer);
            for (let i = 0, n = data.length; i < n; i++) {
                view.fill(data[i], i);
            }
            return new BinaryBuffer(view.buffer);
        }

        public toString(): string {
            let szText: string = "";
            let nOldReadPos: number = this.getCurrentReadPos();
            this.setReadPosition(0);
            for (let i = 0; i < this.getCount(); i++) {
                szText = szText + this.getUint8()[1].toString() + ", ";
            }
            this.setReadPosition(nOldReadPos);
            return szText;
        }
        //模擬Unity的BytesReader
        public ReadAttatchedLengthBytes(): BinaryBuffer {
            let length = this.getUint16()[1];
            let arrTemp: number[] = [];
            for (let i = 0; i < length; i++) {
                arrTemp.push(this.getUint8()[1]);
            }
            return this.GetBinaryBuffer(arrTemp);
        }
        public ReadBool(): boolean {
            return (this.getUint8()[1]) ? true : false;
        }

        public readUnsignedByte(): number {
            return this.getUint8()[1];
        }

        public ReadByte(): number {
            return this.getUint8()[1];
        }

        public ReadBigEndianUShort(): number {
            return this.getUint16()[1];
        }

        public ReadBigEndianULong(num: number): dcodeIO.Long {
            return this.getPositiveLongByBig(num)[1];
        }

        public ReadLittleEndianULong(num: number): dcodeIO.Long {
            if (num = 8)
                return this.getLong(true)[1];
            else
                window.alert("ReadLittleEndianULong:無此方法");
        }

        public ReadBigEndianUInt(num: number) {
            return this.getPositiveLongByBig(num)[1].toNumber();
        }

        public readInt(): number {
            return this.getInt32()[1];
        }

        public set Position(value: number) {
            this.setReadPosition(value);
        }

        public get Position(): number {
            return this.getCurrentReadPos();
        }

        public GetBinaryBuffer(arrTemp: number[]): BinaryBuffer {
            let binaryBufferWriter: BinaryBufferWriter = new BinaryBufferWriter();
            binaryBufferWriter.addByteNumberArray(arrTemp);

            let arrayBuffer: ArrayBuffer = binaryBufferWriter.toArrayBuffer();
            let data = new BinaryBuffer(arrayBuffer);
            return data;
        }

        public static GetBinaryBuffer(arrTemp: number[]): BinaryBuffer {
            let binaryBufferWriter: BinaryBufferWriter = new BinaryBufferWriter();
            binaryBufferWriter.addByteNumberArray(arrTemp);

            let arrayBuffer: ArrayBuffer = binaryBufferWriter.toArrayBuffer();
            let data = new BinaryBuffer(arrayBuffer);
            return data;
        }

        private m_Buffer: ArrayBuffer = null;
        private m_DataView: DataView = null;
        private m_nReadIndex: number = 0;
    }


    interface IBinBufferParser {
        Parse(buffer: BinaryBuffer, ...params: any): void;
    }

    class HalfByte_IntArray implements IBinBufferParser {
        byteSize: number = 0;
        value: number[] = [];

        constructor(byteSize: number) {
            this.byteSize = byteSize;
        }

        Parse(buffer: BinaryBuffer): void {
            this.value = buffer.getBytesArrayAndUnzip(this.byteSize);
        }
    }

    class IntArray implements IBinBufferParser {
        value: number[] = [];
        Parse(buffer: BinaryBuffer, amount: number): void {
            for (let i = 0; i < amount; i++) {
                this.value.push(buffer.getByte()[1]);
            }
        }
    }

    class SizeBegin_IntArray implements IBinBufferParser {
        value: number[] = [];

        Parse(buffer: BinaryBuffer): void {
            this.value = buffer.getBytesArray_WithLength();
        }
    }

    type IconDataProcessor = (list: IconData[]) => IconData[];
    type Item = [string, string | number | BoardData];
    type Line = [string, Item[]];
    type Section = [string, Item[] | Line[]];
    type Board = [string, BoardData];
    type SlotRoundData = [string, (Section | Board)[]];
    type AllRoundDataData = [string, SlotRoundData[]];

    type GameRecordAST = {
        /** 整體細單架構 */
        ast: AllRoundDataData[],
        /** Icon圖片設定 */
        icons?: Record<number, IconConfig>
    }

    type IconConfig = {
        /** Icon路徑 */
        src: string;
        /** Icon寬度 */
        width: number;
        /** Icon高度 */
        height: number;
    };

    type DetailData = {
        /** 中獎圖案List */
        winIconSymbolList: number[];
        /** 中獎賠率List */
        odds: number[];
        /** 中獎線號List */
        lineID?: number[];
        /** 百搭路徑組合數量List */
        megaWayCombinationCount?: number[];
    }

    enum SlotDataStringType {
        /**遊戲模式*/
        gameMode = "gamemode",
        /**細單紀錄*/
        records = "records",
        /**當局Spin紀錄 */
        round = "round",
        /**當次顯示的標題 */
        title = "title",
        /**當次盤面 */
        board = "board",
        /**當次說明 */
        summary = "summary",
        /**詳細中獎資訊 */
        details = "details",
        /**分行 */
        line = "line",
        /**文字顯示 */
        text = "text",
        /**圖片編號 */
        icon = "icon",
        /**數字 */
        number = "number",
        /**運算符號 */
        symbol = "symbol",
    }

    enum SlotDataGameModeType {
        normal = "一般遊戲",
        free = "免費遊戲",
        bonus = "獎勵遊戲"
    }

    class SlotDataParser {
        // /**使用者設定 */
        // public slotDataConfig: SlotDataConfig = null;
        /**整個細單紀錄 */
        protected steps: any[] = [];
        /**單次盤面紀錄 */
        protected oneRound: (Section | Board)[] = [];
        /**當局所有盤面紀錄 */
        protected allRoundData: SlotRoundData[] = [];
        /**下注金額 */
        protected bet: number = 0;

        /**
         * 建立SlotDataParser
         * @param config 設定檔
         * @param bet 下注金額
         */
        constructor(bet: number) {
            //this.slotDataConfig = config;
            this.bet = bet;
        }

        /**
         * 組裝要顯示的文字
         * @param tag  Key值
         * @param value 顯示文字
         * @returns 當次文字排序
         */
        public createItem(key: string, value: string | number): Item {
            return [key, value];
        }

        /**
         * 組裝當次區塊文字排序
         * @param tag  Key值
         * @param arr 文字排序
         * @returns 當次盤面文字排序
         */
        public createSection(tag: string, arr: Item[] | Line[]): Section {
            return [tag, arr];
        }

        /**
         * 組裝當次盤面Icon紀錄
         * @param tag  Key值
         * @param board 盤面資訊
         * @returns 當次盤面Icon紀錄
         */
        public createBoard(tag: string, board: BoardData): Board {
            return [tag, board];
        }

        /**
         * 組裝當次盤面紀錄
         * @param tag  Key值
         * @param round 當次盤面紀錄 
         * @returns 當次盤面紀錄
         */
        public createRound(tag: string, round: (Section | Board)[]): SlotRoundData {
            return [tag, round];
        }

        /**
         * 組裝此局全部盤面紀錄
         * @param tag  Key值
         * @param allRoundData 當前盤面紀錄 
         * @returns 此局全部盤面紀錄
         */
        public createAllRoundData(tag: string, allRoundData: SlotRoundData[]): AllRoundDataData {
            return [tag, allRoundData];
        }

        /**
         * 設置此局遊戲模式，如果下局盤面紀錄與此局盤面紀錄不一樣，再重新呼叫一次
         * @param gameMode 遊戲模式
         * @returns  SlotDataParser，會把當前資料記錄起來
         */
        public setGameMode(gameMode: string): SlotDataParser {
            const item = this.createItem(SlotDataStringType.text, gameMode);
            const section = this.createSection(SlotDataStringType.gameMode, [item]);
            this.steps.push(section);
            return this;
        }

        /**
         * 設置盤面Title，由使用者組裝要顯示的資訊
         * @param items 顯示的資訊
         * @returns  SlotDataParser，會把當前資料記錄起來
         */
        public setTitle(items: Item[]): SlotDataParser {
            const section = this.createSection(SlotDataStringType.title, items);
            this.oneRound.push(section);
            return this;
        }

        /**
         * 設置盤面資訊，由使用者組裝要顯示的資訊
         * @param items 顯示的資訊
         * @returns  SlotDataParser，會把當前資料記錄起來
         */
        public setSummary(items: Item[]): SlotDataParser {
            const section = this.createSection(SlotDataStringType.summary, items);
            this.oneRound.push(section);
            return this;
        }

        /**
         * 設置盤面資訊，由使用者組裝要顯示的資訊，使用後會置中
         * @param items 顯示的資訊
         * @returns  SlotDataParser，會把當前資料記錄起來
         */
        public setLineSummary(items: Line[]): SlotDataParser {
            const section = this.createSection(SlotDataStringType.summary, items);
            this.oneRound.push(section);
            return this;
        }

        /**
         * 設置詳細中獎資訊，由使用者組裝要顯示的資訊
         * @param items 顯示的資訊
         * @returns  SlotDataParser，會把當前資料記錄起來
         */
        public setDetailDescription(items: Line[]): SlotDataParser {
            let section: Section = null;
            if (items.length === 0) {
                section = this.createSection(SlotDataStringType.details, [this.createItem(SlotDataStringType.text, "無中獎")]);
            }
            else {
                section = this.createSection(SlotDataStringType.details, items);
            }
            this.oneRound.push(section);
            return this;
        }

        /**
         * 設置盤面詳細得分資訊，由工具組裝
         * @param isWin 是否贏分 
         * @param detailDataList 詳細得分，{@link DetailData}可根據不同的遊戲類型傳入不同的類型 
         * @returns SlotDataParser，會把當前資料記錄起來
         */
        public setDetail(isWin: boolean, detailDataList?: DetailData): SlotDataParser {
            let section: Section = null;
            if (!isWin) {
                section = this.createSection(SlotDataStringType.details, [
                    this.createItem(SlotDataStringType.text, "無中獎")
                ]);
            }
            else {
                const winSection = [];
                for (let i = 0; i < detailDataList.winIconSymbolList.length; i++) {
                    const allDetails: Item[] = [];
                    const score = detailDataList.megaWayCombinationCount !== undefined ?
                        detailDataList.odds[i] * this.bet * detailDataList.megaWayCombinationCount[i] : detailDataList.odds[i] * this.bet;
                    allDetails.push(this.createItem(SlotDataStringType.icon, detailDataList.winIconSymbolList[i]))
                    allDetails.push(this.createItem(SlotDataStringType.number, this.bet))
                    allDetails.push(this.createItem(SlotDataStringType.symbol, "*"))
                    allDetails.push(this.createItem(SlotDataStringType.number, detailDataList.odds[i]))
                    if (detailDataList.megaWayCombinationCount !== undefined) {
                        allDetails.push(this.createItem(SlotDataStringType.symbol, "*"))
                        allDetails.push(this.createItem(SlotDataStringType.number, detailDataList.megaWayCombinationCount[i]))
                    }
                    allDetails.push(this.createItem(SlotDataStringType.symbol, "="))
                    allDetails.push(this.createItem(SlotDataStringType.number, score.fixed()))
                    if (detailDataList.lineID !== undefined) {
                        allDetails.push(this.createItem(SlotDataStringType.symbol, "("))
                        allDetails.push(this.createItem(SlotDataStringType.text, "線"))
                        allDetails.push(this.createItem(SlotDataStringType.number, (detailDataList.lineID[i] + 1)))
                        allDetails.push(this.createItem(SlotDataStringType.symbol, ")"))
                    }
                    winSection.push(this.createSection(SlotDataStringType.line, allDetails));
                }
                section = this.createSection(SlotDataStringType.details, winSection);
            }

            this.oneRound.push(section);
            return this;
        }

        /**
         * 將先前的一局盤面紀錄包裝，並清空一局盤面紀錄
         * @returns SlotDataParser，會把當前資料記錄起來
         */
        public combineOneRoundData(): SlotDataParser {
            const round: SlotRoundData = this.createRound(SlotDataStringType.round, this.oneRound);
            this.allRoundData.push(round);
            this.oneRound = [];
            return this;
        }

        /**
         * 設置一次盤面紀錄結束
         * @param isOneRoundEnd 判斷是否為當局最後一次盤面紀錄，有ReSpin請設False
         * @returns SlotDataParser 會把當前資料記錄起來
         */
        public setRecords(): SlotDataParser {
            const allRoundData = this.createAllRoundData(SlotDataStringType.records, this.allRoundData);
            this.steps.push(allRoundData);
            this.allRoundData = [];
            return this;
        }

        /**
         * 獲取細單最終結果
         * @returns SlotDataParser紀錄的整體細單架構
         */
        public getFinalSlotData(): AllRoundDataData[] {
            return this.steps;
        }

        /**
         * 處理細單盤面，在{@link processors}裡放入需要額外處理的盤面功能，會按照順序執行
         * EX:標記顏色{@link setMark}，需要合併{@link mergesIconData}，多層圖案顯示{@link addIconList}
         * @param row 盤面高度
         * @param col 盤面寬度
         * @param iconList 盤面資料
         * @param processors 擴充功能
         * @param maxWidth 盤面最大顯示寬
         * @returns SlotDataParser 會把盤面資料記錄起來
         */
        public processIconData(row: number, col: number, iconList: number[], processors: IconDataProcessor[], maxWidth?: number): SlotDataParser {
            const baseList = this.setIconList(row, iconList);
            const showBoard: IconData[] = processors.reduce((list, processor) => processor(list), baseList);
            this.setBoard(row, col, showBoard, maxWidth);
            return this;
        }

        /**
         * 設置細單盤面Icon的架構
         * @param row 盤面高度
         * @param col 盤面寬度
         * @param showBoard 盤面IconList
         * @param maxWidth  盤面最大寬
         * @returns 
         */
        public setBoard(row: number, col: number, showBoard: IconData[], maxWidth?: number): SlotDataParser {
            const board: BoardData = new BoardData(col, row, showBoard, maxWidth);
            const section = this.createBoard(SlotDataStringType.board, board);
            this.oneRound.push(section);
            return this;
        }

        /**
         * 根據iconList，設定每個Icon
         * @param row 盤面高度
         * @param col 盤面寬度
         * @param iconList 盤面Icon
         * @returns 盤面Icon資訊
         */
        public setIconList(row: number, iconList: number[]): IconData[] {
            const baseList = iconList.map((icon, i) => {
                const data = new IconData();
                data.icon = icon;
                data.x = Math.floor(i / row) + 1;
                data.y = (i % row) + 1;
                data.width = 1;
                data.height = 1;
                return data;
            });
            return baseList;
        }

        /**
         * 設置整體標記，可多次標記顏色
         * @param set2DPos 標記的2D位置
         * @param color 顏色 請傳入"#RRGGBB"
         * @returns 合併後的盤面 請放在{@link processIconData}的processors陣列裡
         */
        public setMark(set2DPos: number[][], color: string): IconDataProcessor {
            return (list) => list.map((data) => {
                const xIndex = data.x - 1;
                const yIndex = data.y - 1;
                if (set2DPos[xIndex]) {
                    if (set2DPos[xIndex].includes(yIndex)) {
                        data.mark = true;
                        data.markColor = color;
                    }
                }
                return data;
            });
        }

        /**
         * 添加多層圖案，請按照順序填入 會抓取每個資料的相對位置做處理
         * @param zIndex icon的層級從2開始
         * @param row 盤面高度
         * @param posList 新增加icon的位置
         * @param iconList 新增加icon相對應的圖案
         * @param size icon的大小，可不放默認為{@link initNewSize}，輸入的話請放[[width1,height1],[width2,height2]...]
         * @returns 合併後的盤面，請放在{@link processIconData}的processors陣列裡
         */
        public addIconList(zIndex: number, row: number, posList: number[], iconList: number[], size: number[][] = []): IconDataProcessor {
            return (list) => {
                if (size.length === 0) {
                    size = this.initNewSize(posList.length);
                }

                posList.forEach((pos, i) => {
                    const data = new IconData();
                    data.icon = iconList[i];
                    data.x = Math.floor(pos / row) + 1;
                    data.y = (pos % row) + 1;
                    data.z = zIndex;
                    data.width = size[i][0];
                    data.height = size[i][1];
                    list.push(data);
                })
                return list;
            }
        }

        /**
         * 初始化icon的大小，都為[1,1]
         * @returns 符合盤面Icon數量的[1,1]陣列
         */
        private initNewSize(iconLength: number): number[][] {
            const size = [];
            for (let i = 0; i < iconLength; i++) {
                size.push([1, 1]);
            }
            return size;
        }

        /**
         * 設置盤面上Icon的文字，會根據位置陣列Index抓取相對應的文字
         * @param posList 位置陣列
         * @param textList 文字陣列
         * @returns 合併後的盤面，請放在{@link processIconData}的processors陣列裡
         */
        public setIconText(posList: number[], textList: string[]): IconDataProcessor {
            return (list: IconData[]) => {
                for (let i = 0; i < posList.length; i++) {
                    const pos = posList[i];
                    list[pos].text = textList[i];
                }
                return list;
            }
        }

        /**
         * 會將盤面上的圖示合併，請傳入符合盤面的長度，並以大於0的數字分組
         * EX:3*5盤面，傳入[0,0,1,2,2,1..]，會將第2個位置與第5個位置合併以及第3個位置與第4個位置合併
         * @param merges 合併模板
         * @returns 合併後的盤面，請放在{@link processIconData}的processors陣列裡
         */
        public mergesIconData(merges: number[]): IconDataProcessor {
            return (list: IconData[]) => {
                const groups = new Map<number, number[]>();

                for (let i = 0; i < list.length; i++) {
                    const g = merges[i];
                    if (g > 0) {
                        if (!groups.has(g)) {
                            groups.set(g, []);
                        }
                        groups.get(g).push(i);
                    }
                }

                for (const indices of groups.values()) {
                    let minX = Infinity;
                    let minY = Infinity;
                    let maxX = -Infinity;
                    let maxY = -Infinity;

                    for (const idx of indices) {
                        const c = list[idx];
                        if (c.x < minX) {
                            minX = c.x;
                        }
                        if (c.y < minY) {
                            minY = c.y;
                        }
                        if (c.x > maxX) {
                            maxX = c.x;
                        }
                        if (c.y > maxY) {
                            maxY = c.y;
                        }
                    }

                    const mainIdx = indices.find(idx => list[idx].x === minX && list[idx].y === minY)!;
                    const main = list[mainIdx];
                    main.width = maxX - minX + 1;
                    main.height = maxY - minY + 1;

                    for (const idx of indices) {
                        if (idx !== mainIdx) {
                            list[idx].icon = -1;
                            list[idx].width = 0;
                            list[idx].height = 0;
                        }
                    }
                }

                return list.filter(c => c.icon !== -1 && c.width > 0 && c.height > 0);
            };
        }
    }

