        public static readonly COLLECT_MAX_HAND_PRINT: number = 5;
        public static readonly ORANGE_SYMBOL: number[] = [SymbolType.AUMO, SymbolType.ERHU, SymbolType.D_K, SymbolType.D_Q, SymbolType.D_J];
        public static readonly PURPLE_SYMBOL: number[] = [SymbolType.SIAMESE, SymbolType.DAJU, SymbolType.C_K, SymbolType.C_Q, SymbolType.C_J];

        public static readonly SYMBOL_0_ODDS = [0, 0, 2, 6, 20];
