    const { ALL_ICONS_AMOUNT, REEL_AMOUNT: REELS_AMOUNT, REEL_ICON_AMOUNT: REELS_ICON_AMOUNT, BOARD_ORDER,
        SYMBOL_LIST, INFORMATION_SYMBOL, ODDS_LIST, ORANGE_SYMBOL,
        FG_DEFAULT_MULTIPLE, FG_DEFAULT_FREE_SPIN, COLLECT_MAX_HAND_PRINT } = ConfigGame1015;

    class UtilityGame1015 {
        public static parseServerGameData(betData: string): GameDataGame1015 {
            const gameData: GameDataGame1015 = new GameDataGame1015();

            let buffer = Utility.base64ToBinaryBuffer(betData);
            let slotData = buffer.getBytesArrayAll();

            gameData.fg = [];
            gameData.totalWinOdd = 0;

            const doneProcessGameData = this.processGameData(gameData, slotData);
            return doneProcessGameData;
        }

        private static processGameData(gameData: GameDataGame1015, slotData: number[]): GameDataGame1015 {
            let data: GameDataGame1015 = JSON.parse(JSON.stringify(gameData));
            let ng: RoundResult[] = [];
            let fg: RoundResult[][] = [];
            let fgWin: number = 0;
            const bet = 1;

            const roundCount = this.getBytesAndCheck(slotData.splice(0, 2));

            let roundData = this.processRoundData(slotData, bet, true, [0, 0]);
            ng.push(roundData);

            let fgResult: RoundResult[] = [];
            let nextRoundData: RoundResult = new RoundResult();
            let isFirstInFG: boolean = false;

            while (slotData.length > 0) {
                if (roundData.lockIconPos.length - roundData.winIconPos.length > 0) {
                    roundData = this.processRoundData(slotData, bet, true, [roundData.orangeHandPrintCount, roundData.purpleHandPrintCount]);
                    ng.push(roundData);
                }
                else {
                    nextRoundData = this.processRoundData(slotData, bet, false, [roundData.orangeHandPrintCount, roundData.purpleHandPrintCount]);

                    if (!isFirstInFG) {
                        isFirstInFG = true;

                        const orangeHandPrintCount = this.calculationHandPrint(roundData.orangeHandPrintCount);
                        const purpleHandPrintCount = this.calculationHandPrint(roundData.purpleHandPrintCount);
                        nextRoundData.multiplyOdds = FG_DEFAULT_MULTIPLE + orangeHandPrintCount[0];
                        nextRoundData.orangeHandPrintCount -= orangeHandPrintCount[0] * COLLECT_MAX_HAND_PRINT;
                        nextRoundData.remainCount = FG_DEFAULT_FREE_SPIN + purpleHandPrintCount[0];
                        nextRoundData.purpleHandPrintCount -= purpleHandPrintCount[0] * COLLECT_MAX_HAND_PRINT;
                        nextRoundData.odds *= nextRoundData.multiplyOdds;
                        nextRoundData.score *= nextRoundData.multiplyOdds;
                    }
                    else {
                        nextRoundData.multiplyOdds = roundData.multiplyOdds;
                        nextRoundData.remainCount = roundData.remainCount;
                        nextRoundData.odds *= nextRoundData.multiplyOdds;
                        nextRoundData.score *= roundData.multiplyOdds;
                    }


                    const orangeHandPrintCount = this.calculationHandPrint(nextRoundData.orangeHandPrintCount);
                    nextRoundData.multiplyOdds += orangeHandPrintCount[0];
                    nextRoundData.orangeHandPrintCount = orangeHandPrintCount[1];

                    const purpleHandPrintCount = this.calculationHandPrint(nextRoundData.purpleHandPrintCount);
                    nextRoundData.remainCount += purpleHandPrintCount[0];
                    nextRoundData.purpleHandPrintCount = purpleHandPrintCount[1];

                    roundData = nextRoundData;
                    fgResult.push(roundData);
                    fgWin += roundData.score;
                    if (!roundData.isWin) {
                        fgResult.forEach((value) => {
                            value.remainCount -= 1;
                        });
                        fg.push(fgResult);
                        fgResult = [];
                    }
                }
            }

            let totalScore: number = 0;
            let fgScore: number = 0;
            let totalWinOdd: number = 0;

            for (const data of ng) {
                totalScore += data.score;
                data.totalScore = parseFloat(totalScore.toFixed(4));
                totalWinOdd += data.odds;
            }

            for (let data of fg) {
                for (const value of data) {
                    fgScore += value.score;
                    value.fgScore = parseFloat(fgScore.toFixed(4));
                    totalScore += value.score;
                    value.totalScore = parseFloat(totalScore.toFixed(4));
                    totalWinOdd += value.odds;
                }
            }


            data.ng = ng;
            data.fg = fg;
            data.fgWin = parseFloat(fgWin.toFixed(4));
            data.totalWinOdd = parseFloat(totalWinOdd.toFixed(4));
            return data;
        }

        private static processRoundData(slotData: number[], bet: number, isNG: boolean, previousHandPrint: number[]): RoundResult {
            let result: number[] = this.changeResultToReelData(slotData.splice(0, ALL_ICONS_AMOUNT));

            let lockPos: number[] = [];
            result.forEach((value, index) => {
                if (value === INFORMATION_SYMBOL) {
                    lockPos.push(index);
                }
            });

            let allMatchPayTable = new AllMatchPayTable([], ODDS_LIST, SYMBOL_LIST);
            let winMap = allMatchPayTable.getAllMatchWinData(result, REELS_AMOUNT, REELS_ICON_AMOUNT);
            let winIconPos: number[] = [];
            let winDatas: WinDatas[] = [];
            let odds: number = 0;
            let score: number = 0;

            for (let m of winMap) {
                winIconPos.push(...m.Pos);
                let winData: WinDatas = new WinDatas();
                winData.winIconSymbolID = m.WinSymbolID;
                winData.winOdds = parseFloat((m.Odd / m.OneMatchPos.length).toFixed(4));
                winData.winCombination = m.OneMatchPos.length;
                if (ORANGE_SYMBOL.includes(m.WinSymbolID)) {
                    winData.orangePos.push(...m.Pos);
                }
                else {
                    winData.purplePos.push(...m.Pos);
                }
                winDatas.push(winData);
                odds += m.Odd;
            }
            score = odds * bet;
            winIconPos = winIconPos.set();
            winIconPos = winIconPos.sort((a, b) => a - b);

            let winIconCount = 0;
            let unLockPos: number[] = [];
            let unLockStartPos: number[] = [];
            if (isNG) {
                winIconCount = slotData.shift() || 0;
            }
            if (winIconCount > 0) {
                let unLockCount = slotData.splice(0, winIconCount * 2);
                unLockCount.forEach((value, index) => {
                    if (index % 2 !== 0) {
                        unLockPos.push(value);
                    }
                });
                unLockStartPos = unLockCount.filter((value) => !unLockPos.includes(value));
                unLockStartPos = this.changeServerOrderToBoardOrder(unLockStartPos);
                unLockPos = this.changeServerOrderToBoardOrder(unLockPos);
            }

            let orangeHandPrintCount = previousHandPrint[0];
            let purpleHandPrintCount = previousHandPrint[1];
            if (lockPos.length - unLockPos.length <= 0 && winMap.length > 0) {
                for (let m of winMap) {
                    const set = new Set(unLockStartPos);
                    if (ConfigGame1015.ORANGE_SYMBOL.includes(m.WinSymbolID)) {
                        orangeHandPrintCount += m.Pos.filter((value) => !set.has(value)).length;
                    }
                    else if (ConfigGame1015.PURPLE_SYMBOL.includes(m.WinSymbolID)) {
                        purpleHandPrintCount += m.Pos.filter((value) => !set.has(value)).length;
                    }
                }
            }

            const data: RoundResult = {
                result: result,
                lockIconPos: lockPos,
                unLockStartPos: unLockStartPos,
                unLockPos: unLockPos,
                orangeHandPrintCount: orangeHandPrintCount,
                purpleHandPrintCount: purpleHandPrintCount,
                multiplyOdds: 0,
                remainCount: 0,
                isWin: odds > 0,
                winIconPos: winIconPos,
                winData: winDatas,
                score: parseFloat(score.toFixed(4)),
                odds: parseFloat(odds.toFixed(4)),
                fgScore: 0,
                totalScore: 0
            };
            return data;
        }

        private static calculationHandPrint(previousHandPrint: number): number[] {
            if (previousHandPrint >= COLLECT_MAX_HAND_PRINT) {
                let add = Math.floor(previousHandPrint / COLLECT_MAX_HAND_PRINT);
                let handPrint = previousHandPrint - add * COLLECT_MAX_HAND_PRINT;
                return [add, handPrint];
            }
            return [0, previousHandPrint];
        }

        private static changeServerOrderToBoardOrder(pos: number[]): number[] {
            let newPos: number[] = [];
            pos.forEach((value) => {
                newPos.push(BOARD_ORDER[value]);
            });
            return newPos;
        }

        private static changeResultToReelData(result: number[]): number[] {
            let reel0 = [];
            let reel1 = [];
            let reel2 = [];
            let reel3 = [];
            let reel4 = [];
            for (let i = 0; i < result.length; i++) {
                switch (i % REELS_AMOUNT) {
                    case 0:
                        reel0.push(result[i]);
                        break;
                    case 1:
                        reel1.push(result[i]);
                        break;
                    case 2:
                        reel2.push(result[i]);
                        break;
                    case 3:
                        reel3.push(result[i]);
                        break;
                    case 4:
                        reel4.push(result[i]);
                        break;
                }
            }
            return [...reel0, ...reel1, ...reel2, ...reel3, ...reel4];
        }

        private static getBytesAndCheck(slotData: number[]): number {
            return (slotData[0] << 8) | slotData[1];
        }
    }

    class AllMatchPayTable {
        protected readonly wild: number[];
        protected readonly payTable: number[][];
        protected readonly iconList: number[];
        protected reelAmount: number;
        protected symbolLength: number;

        /**
         * @param wild WILD圖示
         * @param oddList 賠率表
         * @param iconList 中獎圖示表 (將有賠率的連線中獎圖示放入，SCATTER請另外算)
         */
        constructor(wild: number[], oddList: number[][], iconList: number[]) {
            this.wild = wild;
            this.iconList = iconList;
            this.payTable = oddList;
        }

        /**
         * @param iconData 盤面
         * @param reelAmount 滾輪數量
         * @param symbolLength 單一輪有幾個圖示
         * @return 中獎圖示,賠率,贏的位置,輪播位置，中獎2D位置
         */
        public getAllMatchWinData(iconData: number[], reelAmount: number, symbolLength: number): WinData[] {
            this.reelAmount = reelAmount;
            this.symbolLength = symbolLength;
            const icon2DData = this.convertSymbolTo2DArray(iconData);
            return this.allMatchWinData(icon2DData);
        }

        protected allMatchWinData(icon2DData: number[][]): WinData[] {
            let matchWinData: WinData[] = [];
            for (let icon of this.iconList) {
                const oneIconMatchMap = this.calculateOneIconAllMatch(icon, icon2DData);
                for (const [key, value] of oneIconMatchMap) {
                    const Win2DPos = this.convertWinIndexTo2DArray(value.Pos);
                    const winData = new WinData(key, value.Odd, value.Pos, value.OneMatchPos, Win2DPos);
                    matchWinData.push(winData);
                }
            }
            return matchWinData;
        }

        protected calculateOneIconAllMatch(icon: number, icon2DData: number[][]): Map<number, PayLineData> {
            const oneIconMatchMap = new Map<number, PayLineData>();
            let combinedWire: number[][] = Array.from({ length: 0 }, () => []);
            let AllPosList: number[] = [];
            let tempOdds = 0;
            let tempCount = 1;//計算分出去的條數
            for (let i = 0; i < this.reelAmount; i++) {
                const newLineOdds = this.payTable[icon][i];
                const hasWild = this.wild.some(value => icon2DData[i].includes(value));//如果需要WILD都要匹配 some=>every
                if (icon2DData[i].includes(icon) || hasWild) {
                    let winPos: number[] = [];
                    const pos = icon2DData[i].indexesOf(icon).map((x) => x + (i * this.symbolLength));
                    AllPosList = this.mergeTwoArrays(AllPosList, pos);
                    winPos = this.mergeTwoArrays(winPos, pos);
                    if (hasWild) {
                        const wildPos = this.getWildPos(icon2DData[i], (i * this.symbolLength));
                        AllPosList = this.mergeTwoArrays(AllPosList, wildPos);
                        winPos = this.mergeTwoArrays(winPos, wildPos);
                    }
                    combinedWire = this.getCombinedWireArray(combinedWire, winPos);
                    const oneReelMatchCount = icon2DData[i].count(icon) + this.getWildCount(icon2DData[i]);
                    tempCount = (tempCount * oneReelMatchCount).fixed();
                    tempOdds = (newLineOdds * tempCount).fixed();
                    if (tempOdds > 0) {
                        const payLineData = new PayLineData(AllPosList, tempOdds, combinedWire);
                        oneIconMatchMap.set(icon, payLineData);
                    }
                }
                else {
                    break;
                }
            }
            return oneIconMatchMap;
        }

        protected getWildPos(iconList: number[], startPos: number): number[] {
            let wildPosList: number[] = [];
            for (let i = 0; i < this.wild.length; i++) {
                const wildPos: number[] = iconList.indexesOf(this.wild[i]).map((x) => x + startPos);
                wildPosList = wildPosList.concat(wildPos);
            }
            return wildPosList;
        }

        protected getWildCount(iconList: number[]): number {
            let wildTotal: number = 0;;
            for (let i = 0; i < this.wild.length; i++) {
                const wildCount: number = iconList.count(this.wild[i]);
                wildTotal += wildCount;
            }
            return wildTotal;
        }

        protected convertSymbolTo2DArray(iconData: number[]): number[][] {
            let resultData: number[][] = [];

            for (let index = 0; index < this.reelAmount; index++) {
                resultData[index] = iconData.slice(index * this.symbolLength, (index + 1) * this.symbolLength);
            }
            return resultData;
        }

        protected getCombinedWireArray(combinedWire: number[][], posList: number[]): number[][] {
            if (combinedWire.length === 0) {
                combinedWire = posList.map((value) => [value]);
                return combinedWire;
            }
            const newArray: number[][] = [];

            for (let item of combinedWire) {
                for (let pos of posList) {
                    newArray.push([...item, pos]);
                }
            }
            combinedWire = newArray.map((arr) => [...arr]);
            return combinedWire;
        }

        private mergeTwoArrays(targetArray: number[], inputArray: number[]): number[] {
            targetArray = targetArray.concat(inputArray);
            targetArray = targetArray.set();
            return targetArray;
        }

        protected convertWinIndexTo2DArray(winIconPos: number[]): number[][] {
            let resultData: number[][] = Array.from({ length: this.reelAmount }, () => []);
            for (let index = 0; index < winIconPos.length; index++) {
                let reelID = Math.floor(winIconPos[index] / this.symbolLength);
                let pos = winIconPos[index] % this.symbolLength;
                resultData[reelID].push(pos);
            }

            return resultData;
        }
    }

